const input = $json;
if (input.ai_provider === 'precomputed') {
  let replay;
  try { replay = JSON.parse(input.ai_model); } catch (error) { throw new Error('Replay de IA invalido: ai_model deve conter JSON autenticado.'); }
  if (!replay?.structured_output || !replay?.response_id || !replay?.model) throw new Error('Replay de IA incompleto: structured_output, response_id e model sao obrigatorios.');
  return [{json:{...input,ai_provider:'openai',ai_model:replay.model,ai_effective_model:replay.model,ai_response_id:replay.response_id,ai_usage:replay.usage||{},ai_cost_estimate:Number(replay.cost_estimate_usd||0),ai_replayed:true,structured_output:replay.structured_output}}];
}
const text = String(input.message || '');
const normalized = text.toLocaleLowerCase('pt-BR');
const product = /automacao/i.test(normalized) ? 'automacao inteligente' : null;
const structured = {
  schema_version: '1.0',
  intent: {
    name: /(arte|post|conte[uú]do)/i.test(normalized) ? 'create_social_media_art' : 'unknown',
    confidence: 1,
    raw_request: text,
    objective: 'divulgacao de servico',
    product,
    format: 'social_media_post',
    content_type: 'feed',
    brand_identity_required: /(cores? da (nossa|minha) marca|identidade visual)/i.test(normalized)
  },
  automatic_response: 'Recebi o pedido e vou preparar o conteúdo seguindo a identidade visual da marca.',
  briefing: {
    client_id: input.client_id,
    objective: 'divulgacao de servico',
    product,
    content_type: 'feed',
    visual_style: 'premium e tecnologico',
    brand_identity: true,
    requires_generated_image: true,
    status: 'briefing_created',
    elements: ['elemento visual em destaque', 'logo fornecido pela marca', 'texto curto', 'CTA'],
    observations: ['nao inventar metricas', 'nao inventar informacoes sobre o servico', 'usar apenas cores oficiais quando forem cadastradas']
  },
  content: {
    title: 'Automação que transforma',
    subtitle: 'Automacao inteligente em destaque',
    cta: 'Conheça a solução',
    caption: 'Automação e inteligência artificial podem transformar o fluxo de social media, do briefing à publicação. Conheça a solução.',
    hashtags: ['#WebTech', '#InteligenciaArtificial', '#InteligenciaArtificial', '#Automacao'],
    visual_description: 'Composição tecnológica abstrata, profissional e monocromática, com espaço negativo para headline e CTA. A identidade visual é aplicada pelo renderer.',
    image_prompt: 'Visual tecnológico abstrato em preto, branco e cinza, conexões digitais e fluxo de automação, enquadramento quadrado, composição limpa, espaço negativo para texto. Não inserir logo, palavras, telefone ou endereço.',
    assembly_instructions: ['usar canvas 1080x1080', 'posicionar o elemento visual como apoio à mensagem', 'aplicar logo somente a partir do arquivo cadastrado', 'reservar area legivel para titulo e CTA', 'nao inserir informacao nao fornecida']
  }
};
return [{ json: { ...input, structured_output: structured } }];

const input = $json;
const schema = {type:'object',additionalProperties:false,required:['schema_version','intent','automatic_response','briefing','content'],properties:{schema_version:{type:'string'},intent:{type:'object',additionalProperties:false,required:['name','confidence','raw_request','objective','product','format','content_type','brand_identity_required'],properties:{name:{type:'string',enum:['create_social_media_art','unknown']},confidence:{type:'number'},raw_request:{type:'string'},objective:{type:'string'},product:{type:['string','null']},format:{type:'string'},content_type:{type:'string'},brand_identity_required:{type:'boolean'}}},automatic_response:{type:'string'},briefing:{type:'object',additionalProperties:false,required:['client_id','objective','product','content_type','visual_style','brand_identity','requires_generated_image','status','elements','observations'],properties:{client_id:{type:'string'},objective:{type:'string'},product:{type:['string','null']},content_type:{type:'string'},visual_style:{type:'string'},brand_identity:{type:'boolean'},requires_generated_image:{type:'boolean'},status:{type:'string'},elements:{type:'array',items:{type:'string'}},observations:{type:'array',items:{type:'string'}}}},content:{type:'object',additionalProperties:false,required:['title','subtitle','cta','caption','hashtags','visual_description','image_prompt','assembly_instructions'],properties:{title:{type:'string'},subtitle:{type:'string'},cta:{type:'string'},caption:{type:'string'},hashtags:{type:'array',items:{type:'string'}},visual_description:{type:'string'},image_prompt:{type:'string'},assembly_instructions:{type:'array',items:{type:'string'}}}}}};
const instructions = 'Você é um agente de social media. Responda somente no schema solicitado. Não invente preços, produtos, cores, fontes, logo, endereço ou informações ausentes. A resposta automática deve ser curta em português do Brasil.';
const prompt = JSON.stringify({request:input.message,brand_profile:input.brand_profile});
const model = !input.ai_model || input.ai_model === 'mock-v1' ? 'gpt-5-mini' : input.ai_model;
return [{json:{...input,ai_model:model,openai_request:{model,store:false,instructions,input:prompt,text:{format:{type:'json_schema',name:'social_media_content',strict:true,schema},verbosity:'low'}}}}];

const response = $json;
const context = $('Montar Requisicao OpenAI').first().json;
const text = response.output_text || (response.output || []).flatMap(item => item.content || []).find(item => item.type === 'output_text')?.text;
if (!text) throw new Error('A OpenAI nao retornou output_text.');
const usage = response.usage || {};
const inputTokens = Number(usage.input_tokens || 0);
const cachedTokens = Number(usage.input_tokens_details?.cached_tokens || 0);
const outputTokens = Number(usage.output_tokens || 0);
const aiCostEstimate = ((inputTokens - cachedTokens) * 0.25 + cachedTokens * 0.025 + outputTokens * 2) / 1000000;
return [{json:{...context,structured_output:JSON.parse(text),ai_response_id:response.id,ai_usage:usage,ai_effective_model:response.model || context.ai_model,ai_cost_estimate:aiCostEstimate}}];

const input = $json;
const value = input.structured_output;
const required = ['schema_version','intent','automatic_response','briefing','content'];
for (const key of required) if (value?.[key] === undefined) throw new Error(`Structured Output invalido: campo ${key} ausente.`);
const intentRequired = ['name','confidence','raw_request','objective','product','format','content_type','brand_identity_required'];
for (const key of intentRequired) if (value.intent?.[key] === undefined) throw new Error(`Structured Output invalido: intent.${key} ausente.`);
const briefingRequired = ['client_id','objective','product','content_type','visual_style','brand_identity','requires_generated_image','status','elements','observations'];
for (const key of briefingRequired) if (value.briefing?.[key] === undefined) throw new Error(`Structured Output invalido: briefing.${key} ausente.`);
const contentRequired = ['title','subtitle','cta','caption','hashtags','visual_description','image_prompt','assembly_instructions'];
for (const key of contentRequired) if (value.content?.[key] === undefined) throw new Error(`Structured Output invalido: content.${key} ausente.`);
if (!Array.isArray(value.content.hashtags) || !Array.isArray(value.content.assembly_instructions)) throw new Error('Structured Output invalido: arrays esperados.');
return [{json:{...input,structured_output:value,structured_output_valid:true}}];
